import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    static char[][] grid;

    static String solve(int r, int c, int size) {
        char first = grid[r][c];
        boolean same = true;

        for (int i = r; i < r + size && same; ++i) {
            for (int j = c; j < c + size; ++j) {
                if (grid[i][j] != first) {
                    same = false;
